import type { FastifyInstance } from 'fastify';
import { CreateProjectBody, UpdateProjectBody, StageChangeBody, SubStatusChangeBody, ProjectQuery } from './projects.schema.js';
import * as projectsService from './projects.service.js';

export default async function projectsRoutes(fastify: FastifyInstance) {
  fastify.get('/', { onRequest: [fastify.authenticate] }, async (request) => {
    const query = ProjectQuery.parse(request.query);
    const data = await projectsService.list(query);
    return { data };
  });

  fastify.get('/:id', { onRequest: [fastify.authenticate] }, async (request) => {
    const { id } = request.params as { id: string };
    const data = await projectsService.getById(id);
    return { data };
  });

  fastify.post('/', { onRequest: [fastify.authenticate] }, async (request, reply) => {
    const body = CreateProjectBody.parse(request.body);
    const data = await projectsService.create(body);
    return reply.status(201).send({ data });
  });

  fastify.put('/:id', { onRequest: [fastify.authenticate] }, async (request) => {
    const { id } = request.params as { id: string };
    const body = UpdateProjectBody.parse(request.body);
    const data = await projectsService.update(id, body);
    return { data };
  });

  fastify.patch('/:id/stage', { onRequest: [fastify.authenticate] }, async (request) => {
    const { id } = request.params as { id: string };
    const { stage } = StageChangeBody.parse(request.body);
    const data = await projectsService.changeStage(id, stage);
    return { data };
  });

  fastify.patch('/:id/substatus', { onRequest: [fastify.authenticate] }, async (request) => {
    const { id } = request.params as { id: string };
    const { subStatus } = SubStatusChangeBody.parse(request.body);
    const data = await projectsService.changeSubStatus(id, subStatus);
    return { data };
  });

  fastify.delete('/:id', { onRequest: [fastify.authenticate] }, async (request) => {
    const { id } = request.params as { id: string };
    const data = await projectsService.remove(id);
    return { data };
  });
}

import { prisma } from '../../lib/prisma.js';
import { NotFoundError, ValidationError } from '../../lib/errors.js';
import type { CreateProjectBody, UpdateProjectBody } from './projects.schema.js';
import { PROJECT_STAGES, PROJECT_SUB_STATUSES } from './projects.schema.js';

export async function list(query: { stage?: string; peopleId?: string; search?: string }) {
  const where: Record<string, unknown> = {};
  if (query.stage) where.stage = query.stage;
  if (query.peopleId) where.peopleId = query.peopleId;
  if (query.search) {
    where.OR = [
      { name: { contains: query.search } },
      { description: { contains: query.search } },
    ];
  }
  return prisma.project.findMany({
    where,
    include: { people: true, conversations: true },
    orderBy: { createdAt: 'desc' },
  });
}

export async function getById(id: string) {
  const project = await prisma.project.findUnique({
    where: { id },
    include: {
      people: true,
      conversations: { orderBy: { createdAt: 'desc' } },
      files: true,
      requirements: { orderBy: { createdAt: 'desc' } },
      milestones: { orderBy: { createdAt: 'desc' } },
      collaborators: true,
      plans: { orderBy: { createdAt: 'desc' } },
      analytics: { orderBy: { generatedAt: 'desc' } },
    },
  });
  if (!project) throw new NotFoundError('Project');
  return project;
}

export async function create(data: CreateProjectBody) {
  const project = await prisma.project.create({ data });
  if (data.peopleId) {
    await prisma.activity.create({
      data: {
        peopleId: data.peopleId,
        projectId: project.id,
        type: 'created',
        description: `Project "${data.name}" created`,
        metadata: JSON.stringify({ stage: data.stage }),
      },
    });
  }
  return project;
}

export async function update(id: string, data: UpdateProjectBody) {
  await getById(id);
  return prisma.project.update({ where: { id }, data });
}

export async function changeStage(id: string, stage: string) {
  if (!PROJECT_STAGES.includes(stage as typeof PROJECT_STAGES[number])) {
    throw new ValidationError(`Invalid stage. Must be one of: ${PROJECT_STAGES.join(', ')}`);
  }
  await getById(id);
  // Clear subStatus when moving between top-level stages
  const updated = await prisma.project.update({ where: { id }, data: { stage, subStatus: null } });
  await prisma.activity.create({
    data: {
      projectId: id,
      type: 'stage_changed',
      description: `Project stage changed to ${stage}`,
      metadata: JSON.stringify({ newStage: stage }),
    },
  });
  return updated;
}

export async function changeSubStatus(id: string, subStatus: string) {
  const project = await getById(id);
  const validSubs = PROJECT_SUB_STATUSES[project.stage];
  if (!validSubs || !validSubs.includes(subStatus as typeof validSubs[number])) {
    const valid = validSubs ? validSubs.join(', ') : '(no sub-statuses for this stage)';
    throw new ValidationError(`Invalid sub-status for stage "${project.stage}". Valid options: ${valid}`);
  }
  const updated = await prisma.project.update({ where: { id }, data: { subStatus } });
  await prisma.activity.create({
    data: {
      projectId: id,
      type: 'stage_changed',
      description: `Sub-status changed to ${subStatus}`,
      metadata: JSON.stringify({ newSubStatus: subStatus }),
    },
  });
  return updated;
}

export async function remove(id: string) {
  await getById(id);
  await prisma.project.delete({ where: { id } });
  return { success: true };
}

import { z } from 'zod/v4';

export const PROJECT_STAGES = [
  'Contact', 'Opportunity', 'Proposal', 'Implementation',
  'Onboarding', 'Live', 'Validated',
] as const;

/** Sub-statuses per stage: which sub-status values are valid for each stage */
export const PROJECT_SUB_STATUSES: Record<string, readonly string[]> = {
  Proposal: [
    'Proposal Preparation',
    'Proposal Accepted',
    'Waiting for Contract & Payment',
  ] as const,
};

export const CreateProjectBody = z.object({
  name: z.string().min(1),
  description: z.string().optional().nullable(),
  stage: z.string().default('Contact'),
  subStatus: z.string().optional().nullable(),
  value: z.number().positive().optional().nullable(),
  peopleId: z.string(),
});

export const UpdateProjectBody = CreateProjectBody.partial();

export const StageChangeBody = z.object({
  stage: z.enum(PROJECT_STAGES),
});

export const SubStatusChangeBody = z.object({
  subStatus: z.string(),
});

export const ProjectQuery = z.object({
  stage: z.string().optional(),
  peopleId: z.string().optional(),
  search: z.string().optional(),
});

export type CreateProjectBody = z.infer<typeof CreateProjectBody>;
export type UpdateProjectBody = z.infer<typeof UpdateProjectBody>;

