import Fastify from 'fastify';
import cors from '@fastify/cors';
import jwt from '@fastify/jwt';
import { config } from './config.js';
import { errorHandler } from './lib/errors.js';
import authPlugin from './plugins/auth.js';

// Module routes
import authRoutes from './modules/auth/auth.routes.js';
import peopleRoutes from './modules/people/people.routes.js';
import projectsRoutes from './modules/projects/projects.routes.js';
import conversationsRoutes from './modules/conversations/conversations.routes.js';
import requirementsRoutes from './modules/requirements/requirements.routes.js';
import milestonesRoutes from './modules/milestones/milestones.routes.js';
import collaboratorsRoutes from './modules/collaborators/collaborators.routes.js';
import plansRoutes from './modules/plans/plans.routes.js';
import filesRoutes from './modules/files/files.routes.js';
import dashboardRoutes from './modules/dashboard/dashboard.routes.js';
import mcpPlugin from './modules/mcp/mcp.plugin.js';

export async function buildApp() {
  const app = Fastify({ logger: true });

  // Error handler
  app.setErrorHandler(errorHandler);

  // CORS
  await app.register(cors, { origin: true });

  // JWT
  await app.register(jwt, { secret: config.jwtSecret });

  // Auth decorator
  await app.register(authPlugin);

  // Routes
  await app.register(authRoutes, { prefix: '/api/auth' });
  await app.register(peopleRoutes, { prefix: '/api/people' });
  await app.register(projectsRoutes, { prefix: '/api/projects' });
  await app.register(conversationsRoutes, { prefix: '/api/projects' });
  await app.register(requirementsRoutes, { prefix: '/api/projects' });
  await app.register(milestonesRoutes, { prefix: '/api/projects' });
  await app.register(collaboratorsRoutes, { prefix: '/api/projects' });
  await app.register(plansRoutes, { prefix: '/api/projects' });
  await app.register(filesRoutes, { prefix: '/api/projects' });
  await app.register(dashboardRoutes, { prefix: '/api/dashboard' });

  // MCP Server
  await app.register(mcpPlugin);

  // Health check
  app.get('/health', async () => ({ status: 'ok', service: 'ensoria-os' }));

  return app;
}

import type { FastifyError, FastifyReply, FastifyRequest } from 'fastify';

export class AppError extends Error {
  constructor(
    public statusCode: number,
    public code: string,
    message: string,
    public details?: unknown,
  ) {
    super(message);
    this.name = 'AppError';
  }
}

export class NotFoundError extends AppError {
  constructor(resource: string) {
    super(404, 'NOT_FOUND', `${resource} not found`);
  }
}

export class ValidationError extends AppError {
  constructor(message: string, details?: unknown) {
    super(400, 'VALIDATION_ERROR', message, details);
  }
}

export class UnauthorizedError extends AppError {
  constructor(message = 'Unauthorized') {
    super(401, 'UNAUTHORIZED', message);
  }
}

export class ConflictError extends AppError {
  constructor(message: string) {
    super(409, 'CONFLICT', message);
  }
}

export function errorHandler(
  error: FastifyError | AppError | Error,
  _request: FastifyRequest,
  reply: FastifyReply,
) {
  if (error instanceof AppError) {
    return reply.status(error.statusCode).send({
      error: {
        code: error.code,
        message: error.message,
        ...(error.details ? { details: error.details } : {}),
      },
    });
  }

  // Fastify validation errors
  if ('validation' in error && error.validation) {
    return reply.status(400).send({
      error: {
        code: 'VALIDATION_ERROR',
        message: 'Request validation failed',
        details: error.validation,
      },
    });
  }

  console.error('Unhandled error:', error);
  return reply.status(500).send({
    error: {
      code: 'INTERNAL_ERROR',
      message: 'Internal server error',
    },
  });
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { get, post, put, patch, del } from '../lib/api'

export interface Project {
  id: string
  name: string
  description?: string | null
  stage: string
  value?: number | null
  peopleId: string
  subStatus?: string | null
  people?: { id: string; name: string; company?: string | null }
  createdAt: string
  updatedAt: string
  conversations?: unknown[]
  requirements?: unknown[]
  milestones?: unknown[]
  collaborators?: unknown[]
  plans?: unknown[]
  files?: unknown[]
  analytics?: unknown[]
}

export function useProjects(filters?: { stage?: string; peopleId?: string; search?: string }) {
  const params = new URLSearchParams()
  if (filters?.stage) params.set('stage', filters.stage)
  if (filters?.peopleId) params.set('peopleId', filters.peopleId)
  if (filters?.search) params.set('search', filters.search)
  const qs = params.toString()

  return useQuery({
    queryKey: ['projects', filters],
    queryFn: () => get<Project[]>(`/projects${qs ? `?${qs}` : ''}`),
  })
}

export function useProject(id: string) {
  return useQuery({
    queryKey: ['projects', id],
    queryFn: () => get<Project>(`/projects/${id}`),
    enabled: !!id,
  })
}

export function useCreateProject() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (body: Partial<Project>) => post<Project>('/projects', body),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['projects'] }),
  })
}

export function useUpdateProject() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: ({ id, ...body }: Partial<Project> & { id: string }) =>
      put<Project>(`/projects/${id}`, body),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['projects'] }) },
  })
}

export function useDeleteProject() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: (id: string) => del(`/projects/${id}`),
    onSuccess: () => qc.invalidateQueries({ queryKey: ['projects'] }),
  })
}

export function useChangeProjectStage() {
  const qc = useQueryClient()
  return useMutation({
    mutationFn: ({ id, stage }: { id: string; stage: string }) =>
      patch<Project>(`/projects/${id}/stage`, { stage }),
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['projects'] }) },
  })
}

const API_BASE = '/api';

function getToken(): string | null {
  return localStorage.getItem('ensoria_token');
}

export function setToken(token: string) {
  localStorage.setItem('ensoria_token', token);
}

export function removeToken() {
  localStorage.removeItem('ensoria_token');
}

export function getStoredToken(): string | null {
  return getToken();
}

export function isAuthenticated(): boolean {
  return !!getToken();
}

async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
  const token = getToken();
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...((options.headers as Record<string, string>) || {}),
  };
  if (token) headers['Authorization'] = `Bearer ${token}`;

  const res = await fetch(`${API_BASE}${path}`, { ...options, headers });
  const json = await res.json();

  if (!res.ok) {
    const err = json.error || { code: 'UNKNOWN', message: 'Request failed' };
    throw new Error(err.message);
  }

  return json.data;
}

export function get<T>(path: string): Promise<T> {
  return request<T>(path);
}

export function post<T>(path: string, body: unknown): Promise<T> {
  return request<T>(path, { method: 'POST', body: JSON.stringify(body) });
}

export function put<T>(path: string, body: unknown): Promise<T> {
  return request<T>(path, { method: 'PUT', body: JSON.stringify(body) });
}

export function patch<T>(path: string, body: unknown): Promise<T> {
  return request<T>(path, { method: 'PATCH', body: JSON.stringify(body) });
}

export function del<T>(path: string): Promise<T> {
  return request<T>(path, { method: 'DELETE' });
}

